import zipfile, os, re
hits=[]
for root,dirs,files in os.walk('/tmp'):
    for f in files:
        if f.endswith('.xlsx'):
            p=os.path.join(root,f)
            try:
                z=zipfile.ZipFile(p)
                for n in z.namelist():
                    if 'sheet' in n or 'workbook' in n:
                        data=z.read(n).decode('utf-8','replace')
                        if 'Nov 21 (2)' in data or 'Deferred Income Calculation' in data:
                            hits.append((p,n))
                            break
            except Exception as e:
                pass
print('hits', hits)
